INSERT INTO ANIMAL (id_animal, nombre, fecha_nacimiento, sexo, esterilizado, descripcion, sociabilidad, nivel_energia, tiene_enfermedad, enfermedad, estado, fecha_ingreso, es_urgente, id_referencia_salesforce, fecha_sincronizacion, id_centro_adopcion, foto_url) VALUES
    (1, 'Mochi', '2023-06-06', 'MACHO', TRUE, 'Mochi es un gato europeo de 3 años. Es muy sociable y cariñoso con las personas y con otros animales. Es muy juguetón y necesita juego diario y rascadores para gastar energía. Requiere cuidados especiales: gingivoestomatitis crónica: revisiones dentales. Está vacunado, desparasitado y con microchip.', 'ALTO', 'ALTO', TRUE, 'Gingivoestomatitis crónica: revisiones dentales', 'ADOPTADO', '2025-02-06', FALSE, 'a01GsxMegcY8LTvNCa', '2026-05-04 16:06:36', 7, 'https://picsum.photos/seed/animal-1/640/480'),
    (2, 'Ziggy', '2019-11-30', 'MACHO', FALSE, 'Ziggy es un conejo enano macho de 6 años. Se muestra tranquilo y tolera bien la manipulación. Tiene un ritmo pausado y pasa mucho tiempo en reposo. Se entrega con su jaula o terrario y una guía de cuidados.', 'MEDIO', 'BAJO', FALSE, NULL, 'DISPONIBLE', '2025-02-22', FALSE, 'a018kItTQdPM6nRbWp', '2025-02-22 18:40:19', 8, 'https://picsum.photos/seed/animal-2/640/480'),
    (3, 'Zafiro', '2018-04-25', 'MACHO', FALSE, 'Zafiro es un canario macho de 8 años. Es asustadizo y necesita un entorno estable con poca manipulación. Tiene un ritmo pausado y pasa mucho tiempo en reposo. Busca un hogar informado y comprometido con sus necesidades específicas.', 'BAJO', 'BAJO', FALSE, NULL, 'ADOPTADO', '2025-02-24', FALSE, 'a012VyIRdh2BxGWX2T', '2026-04-03 12:06:13', 8, 'https://picsum.photos/seed/animal-3/640/480'),
    (4, 'Sasha', '2023-10-03', 'HEMBRA', TRUE, 'Sasha es una perra mestiza de 3 años. Es muy sociable y cariñosa con las personas y con otros animales. Es muy tranquila: se conforma con paseos cortos y mucha compañía. Requiere cuidados especiales: artrosis: tratamiento con condroprotectores. Está vacunada, desparasitada y con microchip.', 'ALTO', 'BAJO', TRUE, 'Artrosis: tratamiento con condroprotectores', 'DISPONIBLE', '2025-02-25', FALSE, 'a01CsLEytJ3r37vz5k', '2025-02-26 13:55:32', 2, 'https://picsum.photos/seed/animal-4/640/480'),
    (5, 'Milo', '2019-12-11', 'MACHO', TRUE, 'Milo es un gato de 6 años de raza Maine Coon. Es muy sociable y cariñoso con las personas y con otros animales. Es muy plácido y pasa buena parte del día durmiendo al sol. Está vacunado, desparasitado y con microchip.', 'ALTO', 'BAJO', FALSE, NULL, 'DISPONIBLE', '2025-03-02', FALSE, 'a01PKDKaHUouUqkUu4', '2025-03-02 19:47:21', 2, 'https://picsum.photos/seed/animal-5/640/480'),
    (6, 'Manchas', '2021-05-21', 'HEMBRA', FALSE, 'Manchas es un canario hembra de 5 años. Es muy curioso y se acostumbra bien al contacto con las personas. Tiene un ritmo pausado y pasa mucho tiempo en reposo. Requiere cuidados especiales: ácaros en tratamiento. Se entrega con su jaula o terrario y una guía de cuidados.', 'ALTO', 'BAJO', TRUE, 'Ácaros en tratamiento', 'DISPONIBLE', '2025-03-16', TRUE, 'a01d9QS57eeIMu61HU', '2025-03-16 15:17:01', 3, 'https://picsum.photos/seed/animal-6/640/480'),
